mapper.select:
SELECT COUNT(*)
  FROM contact_friend_task_account
 WHERE task_id = #{taskId}

mapper.update:
UPDATE contact_friend_task_account
   SET sent_num = sent_num + 1, updated_at = #{updatedAt}
 WHERE id = #{id}

UPDATE contact_friend_task_account
   SET fail_num = fail_num + 1, updated_at = #{updatedAt}
 WHERE id = #{id}

UPDATE contact_friend_task_account
SET state = 'FAILED', stop_reason = #{reason}, updated_at = #{updatedAt}
WHERE id = #{id} AND state IN ('PENDING', 'RUNNING')

UPDATE contact_friend_task_account
   SET state = 'RUNNING', updated_at = #{updatedAt}
 WHERE id = #{id} AND state = 'PENDING'
